import { sharedWebCopy } from "./sharedUiBindings";
/** Workspace copy. Columns follow UI_LOCALES, not listing output languages. */
export const UI_LOCALES = [
  "en",
  "fr",
  "cz",
  "da",
  "nl",
  "de",
  "el",
  "hr",
  "fi",
  "hu",
  "it",
  "lt",
  "pl",
  "pt",
  "ro",
  "es",
  "sk",
  "sv",
] as const;
export type UiLocale = (typeof UI_LOCALES)[number];
export const workspaceCopy = Object.fromEntries(
  UI_LOCALES.map((code) => [code, sharedWebCopy(code)]),
) as Record<UiLocale, Record<string, string>>;
function rows(table: string) {
  for (const line of table.trim().split("\n")) {
    const values = line.trim().split("|");
    if (
      values.length !== UI_LOCALES.length ||
      values.some((value) => !value.trim())
    )
      throw new Error(
        `Incomplete workspace translation (${values.length}): ${values[0]}`,
      );
    UI_LOCALES.forEach((code, index) => {
      workspaceCopy[code][values[0]] = values[index];
    });
  }
}

